Aquí tienes un componente de login para Angular 15 con las especificaciones solicitadas:

```typescript
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';

@Component({
  selector: 'app-login',
  templateurl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent implements OnInit {
  loginForm!: FormGroup;
  errorMessage?: string;
  successMessage?: string;

  constructor(private formBuilder: FormBuilder) {}

  ngOnInit() {
    this.loginForm = this.formBuilder.group({
      username: ['', [Validators.required, Validators.minLength(5)]],
      password: ['', [Validators.required, Validators.minLength(8)]]
    });
  }

  get f() { return this.loginForm.controls; }

  onSubmit(formDirective: any) {
    const formData = new FormData(formDirective.currentTarget);

    if (formDirective.submitted && this.loginForm.invalid) {
      this.errorMessage = 'Usuario o contraseña no cumple con las validaciones';
      return;
    }

    // Aquí iría la lógica de autenticación
    console.log('formulario enviado:', formData);

    this.successMessage = 'Login exitoso!';
    setTimeout(() => {
      this.clearMessages();
    }, 3000);
  }

  clearMessages() {
    this.errorMessage = undefined;
    this.successMessage = undefined;
  }
}
```

