import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';

@Injectable({
  providedIn: 'root'
})
export class AuthService {
  private baseUrl = 'http://localhost:3000/api/auth'; // URL de tu backend

  constructor(private http: HttpClient) {}

  login(username: string, password: string): Promise<any> {
      const hardcodedUser = 'admin123';
      const hardcodedPassword = 'password123';

      if (username === hardcodedUser && password === hardcodedPassword) {
        return new Promise((resolve) => {
          // Simulando una respuesta de API
          resolve({
            success: true,
            token: 'tu_token_generado_aqui',
            message: 'Login exitoso'
          });
        });
      } else {
        throw new Error('Credenciales incorrectas');
      }
    }



  logout(): Promise<void> {
    // Aquí iría la lógica de cierre de sesión
    return this.http.post(`${this.baseUrl}/logout`, {}).toPromise();
  }

  /* Si necesitas más métodos como recuperación de contraseña, agrégalos aquí */
}
```

